"""Small chat-first project picker and read-only project library controls."""

PROJECT_CHAT_PATCH = r'''
const projectButton=document.createElement('button');projectButton.className='new-chat';projectButton.textContent='Projects';projectButton.id='projectsButton';$('newChat').after(projectButton);
const projectSelectLabel=document.createElement('label');projectSelectLabel.className='hint';projectSelectLabel.textContent='Project ';
const projectSelect=document.createElement('select');projectSelect.id='activeProject';projectSelect.setAttribute('aria-label','Project for new chats');projectSelectLabel.append(projectSelect);$('chatTitle').before(projectSelectLabel);
const projectDialog=document.createElement('dialog');projectDialog.id='projectsDialog';const projectHeading=document.createElement('h2');projectHeading.textContent='Projects';const projectDescription=document.createElement('p');projectDescription.textContent='Registered repositories are inspected read-only. Registration does not clone or modify project files. GitHub references are shown from local Git metadata; no network fetch occurs.';const projectRootLabel=document.createElement('label');projectRootLabel.htmlFor='projectRoot';projectRootLabel.textContent='Local Git repository path';const projectRootInput=document.createElement('input');projectRootInput.id='projectRoot';projectRootInput.type='text';projectRootInput.style.cssText='display:block;width:100%;margin:8px 0;padding:9px';const projectRegister=document.createElement('button');projectRegister.id='registerProject';projectRegister.textContent='Register read-only project';const projectStatus=document.createElement('p');projectStatus.id='projectStatus';projectStatus.className='hint';projectStatus.setAttribute('role','status');const projectRows=document.createElement('div');projectRows.id='projectRows';projectRows.className='knowledge-list';const projectCloseForm=document.createElement('form');projectCloseForm.method='dialog';const projectClose=document.createElement('button');projectClose.className='plain';projectClose.textContent='Close';projectCloseForm.append(projectClose);projectDialog.append(projectHeading,projectDescription,projectRootLabel,projectRootInput,projectRegister,projectStatus,projectRows,projectCloseForm);
document.body.append(projectDialog);let projects=[],selectedProjectId=null;
function updateProjectSelect(){projectSelect.replaceChildren();const none=document.createElement('option');none.value='';none.textContent='General chat';projectSelect.append(none);for(const row of projects){const option=document.createElement('option');option.value=row.project_id;option.textContent=row.display_name+(row.snapshot?' · '+row.snapshot.branch:'');projectSelect.append(option)}projectSelect.value=selectedProjectId||''}
function renderProjects(){const host=$('projectRows');host.replaceChildren();for(const row of projects){const card=document.createElement('div');card.className='knowledge-row';const info=document.createElement('div');const title=document.createElement('strong');title.textContent=row.display_name;const detail=document.createElement('div');detail.className='hint';const snap=row.snapshot;detail.textContent=snap?('Branch '+snap.branch+' · '+snap.commit.slice(0,12)+' · staged '+snap.status.staged_count+', unstaged '+snap.status.unstaged_count+', untracked '+snap.status.untracked_count+' · '+(row.indexing_status||'not indexed')):'Repository unavailable';info.append(title,detail);const actions=document.createElement('div');for(const [label,work] of [['Use in new chat',async()=>{selectedProjectId=row.project_id;updateProjectSelect();projectDialog.close();await startProjectConversation()}],['Refresh',async()=>{const s=$('projectStatus');s.textContent='Indexing approved source files and reading Git status…';const result=await api('/api/projects/'+row.project_id+'/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});s.textContent='Indexed '+result.index.documents_seen+' eligible files; '+result.index.mode+' retrieval is ready.';await refreshProjects()}],['Use in this chat',async()=>{if(!conversationId){selectedProjectId=row.project_id;await startProjectConversation();return}await api('/api/chat/conversations/'+conversationId+'/project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:row.project_id})});selectedProjectId=row.project_id;updateProjectSelect();$('chatTitle').textContent=$('chatTitle').textContent.replace(/ · .+$/,'')+' · '+row.display_name;$('projectStatus').textContent='This conversation is now bound to '+row.display_name+'.'}],['Remove',async()=>{if(!confirm('Remove this project registration? Source files will not be deleted.'))return;await api('/api/projects/'+row.project_id,{method:'DELETE'});if(selectedProjectId===row.project_id)selectedProjectId=null;await refreshProjects()}]]){const button=document.createElement('button');button.textContent=label;button.onclick=async()=>{button.disabled=true;try{await work()}catch(error){$('projectStatus').textContent=error.message}finally{button.disabled=false}};actions.append(button)}card.append(info,actions);host.append(card)}if(!projects.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No projects registered. Add a local Git repository path above.';host.append(empty)}updateProjectSelect()}
async function refreshProjects(){const result=await api('/api/projects');projects=result.projects||[];if(selectedProjectId&&!projects.some(row=>row.project_id===selectedProjectId))selectedProjectId=null;renderProjects()}
async function startProjectConversation(){await newConversation()}
const projectBaseNewConversation=newConversation;newConversation=async()=>{await projectBaseNewConversation();if(selectedProjectId){await api('/api/chat/conversations/'+conversationId+'/project',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:selectedProjectId})});$('chatTitle').textContent='New chat · '+(projects.find(row=>row.project_id===selectedProjectId)?.display_name||'Project')}};
const projectBaseOpenConversation=openConversation;openConversation=async id=>{await projectBaseOpenConversation(id);const row=await api('/api/chat/conversations/'+id);selectedProjectId=row.project_id||null;updateProjectSelect();if(row.project_id){const label=projects.find(item=>item.project_id===row.project_id)?.display_name;$('chatTitle').textContent=row.title+(label?' · '+label:'')}};
const projectBaseSendChat=sendChat;sendChat=async()=>{if(!conversationId&&selectedProjectId)await startProjectConversation();await projectBaseSendChat()};
projectSelect.onchange=()=>{selectedProjectId=projectSelect.value||null};projectButton.onclick=async()=>{projectDialog.showModal();$('projectStatus').textContent='Loading registered projects…';try{await refreshProjects();$('projectStatus').textContent='Git status is local and read-only. Remote refs are cached and may be stale.'}catch(error){$('projectStatus').textContent=error.message}};
$('registerProject').onclick=async()=>{const root=$('projectRoot').value.trim();if(!root){$('projectStatus').textContent='Enter the full local path to an existing Git repository.';return}const button=$('registerProject');button.disabled=true;$('projectStatus').textContent='Validating Git root and recording read-only authorization…';try{const result=await api('/api/projects',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({root,confirmed:true})});selectedProjectId=result.project_id;$('projectRoot').value='';await refreshProjects();$('projectStatus').textContent='Registered '+result.display_name+' read-only. Choose Refresh to index supported source files.'}catch(error){$('projectStatus').textContent=error.message}finally{button.disabled=false}};
const projectConnectBase=connect;connect=async()=>{await projectConnectBase();if(token){try{await refreshProjects()}catch(error){connectionState.textContent+=' · Projects unavailable: '+error.message}}};
'''
